export const TARGET = {
  ANDROID: 'ANDROID',
  IOS: 'IOS',
  WEB: 'WEB',
};

const DEFAULT_FONT_FAMILY = 'Open Sans';

const DEFAULT_FONT_DEFINITIONS = {
  h1: {
    fontSize: 96,
    fontWeight: '300',
    letterSpacing: -1.5,
    lineHeight: 132,
  },
  h2: {
    fontSize: 60,
    fontWeight: '300',
    letterSpacing: -0.5,
    lineHeight: 84,
  },
  h3: {
    fontSize: 48,
    fontWeight: '400',
    letterSpacing: 0,
    lineHeight: 64,
  },
  h4: {
    fontSize: 34,
    fontWeight: '400',
    letterSpacing: 0.25,
    lineHeight: 48,
  },
  h5: {
    fontSize: 24,
    fontWeight: '400',
    letterSpacing: 0,
    lineHeight: 32,
  },
  h6: {
    fontSize: 20,
    fontWeight: '700',
    letterSpacing: 0.25,
    lineHeight: 28,
  },
  body1: {
    fontSize: 16,
    fontWeight: '400',
    letterSpacing: 0.5,
    lineHeight: 24,
  },
  body2: {
    fontSize: 14,
    fontWeight: '400',
    letterSpacing: 0.25,
    lineHeight: 20,
  },
  subtitle1: {
    fontSize: 16,
    fontWeight: '700',
    letterSpacing: 0.15,
    lineHeight: 24,
  },
  subtitle2: {
    fontSize: 14,
    fontWeight: '400',
    letterSpacing: 0.1,
    lineHeight: 20,
  },
  button: {
    fontSize: 14,
    fontWeight: '400',
    letterSpacing: 1.25,
    lineHeight: 20,
    textTransform: 'uppercase',
  },
  caption: {
    fontSize: 12,
    fontWeight: '400',
    letterSpacing: 0.4,
    lineHeight: 16,
  },
  overline: {
    fontSize: 10,
    fontWeight: '400',
    letterSpacing: 2,
    lineHeight: 16,
  },
};

/**
 * getAndroidFamily takes a font family and weight and returns the evaluated font family
 *
 * @param {string} family
 * @param {number} weight
 */
const getAndroidFontFamily = (family, weight) => {
  const baseFamily = family.replace(' ', '');

  if (weight <= 300) return `${baseFamily}-Light`;

  if (weight >= 600) return `${baseFamily}-SemiBold`;

  return `${baseFamily}-Regular`;
};

/**
 * androidAdapter takes a set of styles converts the font family,
 * fontWeight and fontStyle to the android versions
 *
 * @example
 * {
 *  fontFamily: 'Open Sans',
 *  fontWeight: 300
 * } => {
 *  fontFamily: 'OpenSans-Light',
 *  fontWeight: undefined,
 *  fontStyle: undefined,
 * }
 * @param {object} styles
 */
const androidAdapter = (styles) => {
  const { fontFamily, fontWeight, fontStyle } = styles;

  if (!fontFamily || !fontWeight) return styles;

  return {
    ...styles,
    fontFamily: getAndroidFontFamily(fontFamily, fontWeight, fontStyle),
    fontWeight: undefined,
    fontStyle: undefined,
  };
};

const DEFAULT_ADAPTERS = {
  [TARGET.ANDROID]: androidAdapter,
};

/**
 * TextManager
 *
 * The TextManager class is a singleton that manages the current text style groups by allowing
 * for a target to be set. Methods on the Text manager will translate styles to meet the targets
 * needs.
 */
class TextManager {
  constructor() {
    this.fontFamily = DEFAULT_FONT_FAMILY;
    this.target = TARGET.WEB;
    this.adapters = DEFAULT_ADAPTERS;
    this.fontDefinitions = DEFAULT_FONT_DEFINITIONS;

    Object.keys(DEFAULT_FONT_DEFINITIONS).forEach(this.bindDefinition.bind(this));
  }

  /**
   * adaptStyles runs `styles` through the adapters of `target` and gives back the result.
   *
   * @param {string} target
   * @param {object} styles
   */
  adaptStyles(target, styles) {
    const { [target]: adapter } = this.adapters;

    return adapter ? adapter(styles) : styles;
  }

  /**
   * bindDefinition exposes `key` as a property on TextManager
   *
   * @param {string} key
   */
  bindDefinition(key) {
    Object.defineProperty(this, key, {
      configurable: true,
      get: this.getDefinition(key),
    });
  }

  /**
   * getDefinition returns the styles associated with `key` after they have
   * been run through the adapters.
   *
   * @param {string} key
   */
  getDefinition(key) {
    return () => {
      const { [key]: fontDef } = this.fontDefinitions;

      const currentStyles = {
        fontFamily: DEFAULT_FONT_FAMILY,
        ...(fontDef || DEFAULT_FONT_DEFINITIONS[key] || {}),
      };

      return this.adaptStyles(this.target, currentStyles);
    };
  }

  /**
   * setDefinition updates the style definition associated with `key`. The current styles will
   * be passed to `styleFactory` and the expected return of `styleFactory` is the updated styles.
   *
   * @param {string} key
   * @param {func} styleFactory
   */
  setDefinition(key, styleFactory) {
    const didExist = !!this.fontDefinitions[key];
    this.fontDefinitions[key] = styleFactory(this.fontDefinitions[key]);
    if (!didExist) this.bindDefinition(key);
  }

  /**
   * setTarget sets the TextManagers target environment.
   *
   * @param {string} target
   */
  setTarget(target) {
    this.target = target;
  }

  /**
   * setAdapter defines a new style `adapter` for the `target`
   *
   * @param {string} target
   * @param {function} adapter
   */
  setAdapter(target, adapter) {
    this.adapters[target] = adapter;
  }
}

export default new TextManager();
